/**
 * The entrance effect played the moment qualifying loot drops. A style is an
 * optional warning stage (tinted with the secondary colour, lightened into a
 * flash) followed by the main effect (primary/secondary like a beam), then the
 * beam takes over.
 */
@Getter
@RequiredArgsConstructor
public enum FanfareStyle
{
	// the ToA Wardens sequence — warning flash, then the strike, same order as
	// the raid. One model played twice, recoloured per stage. (The anim is
	// actually the Hallowed Sepulchre end-strike, ToA just reuses it)
	LIGHTNING("Lightning strike", lightningRecipe(), lightningRecipe()),

	// ToA Path of Crondis column trap (spotanim 2129) — a circular column that
	// rises out of the ground and sinks back. Single-colour model, so the whole
	// column takes the primary colour (alt anims: 9560 hold, 9561 lower)
	RISING_COLUMN("Rising column", null, BeamRecipe.builder()
		.modelId(46216)
		.animId(9559)
		.primaryFinds(new short[]{20405})
		.ambientAdd(50)
		.contrastAdd(50)
		.loop(false)
		.build()),

	// Combat Achievements tier-reward teleport (spotanim 1950) — a celebratory
	// light column with spinning laurels. Primary drives the column, secondary
	// the ribbon accents; the small gold/green laurel details stay native
	TROPHY_TELEPORT("Trophy teleport", null, BeamRecipe.builder()
		.modelId(42720)
		.animId(9135)
		.primaryFinds(new short[]{-31817, -31813, -31808, -31796, -31784})
		.secondaryFinds(new short[]{912, 926})
		.ambientAdd(30)
		.contrastAdd(12)
		.loop(false)
		.build()),

	// Sins of the Father — Drakan incinerating the Myreque (spotanim 1813). A
	// fiery burst; the flame body takes primary, the bright tips secondary,
	// the little grey ash stays native
	DRAKAN_INCINERATE("Drakan incinerate", null, BeamRecipe.builder()
		.modelId(39815)
		.animId(8746)
		.primaryFinds(new short[]{937, 1984, 1977, 945})
		.secondaryFinds(new short[]{3014})
		.ambientAdd(40)
		.contrastAdd(40)
		.loop(false)
		.build()),

	// the forked bolt a revenant calls down on itself when it heals below half
	// health (spotanim 1221, which Jagex reuses from the God Wars Saradomin light
	// attack). Single-colour model, so the whole bolt takes the primary colour
	REVENANT_HEAL("Revenant heal", null, BeamRecipe.builder()
		.modelId(28163)
		.animId(7075)
		.primaryFinds(new short[]{-31784})
		.ambientAdd(20)
		.contrastAdd(20)
		.loop(false)
		.build()),

	// Yama's phase two meteor (spotanim 3271). It's a projectile, but its own
	// anim does the drop from high up and the shatter on landing. Resized from
	// the real 5x5 down to about 2 tiles, sped up, and stopped as the shards
	// fade. The rock shell takes primary, the molten cracks and flame spikes
	// secondary
	YAMA_METEOR("Yama meteor", null, BeamRecipe.builder()
		.modelId(14813)
		.animId(12114)
		.primaryFinds(new short[]{1556, 1816, 2977})
		.secondaryFinds(new short[]{2892, 4940, 6998, 6096, 7128})
		.resize(51)
		.ambientAdd(30)
		.contrastAdd(100)
		.loop(false)
		.endPercent(90)
		.speedPercent(150)
		.build()),

	// Yama's basic flame attack (spotanim 3247) — flames close in on the tile
	// and burst when he snaps his fingers. Stops before the last few frames,
	// where a stray flame hangs in the air. Flames take primary, the sparks and
	// embers secondary
	YAMA_FLAME("Yama flame", null, BeamRecipe.builder()
		.modelId(16990)
		.animId(12099)
		.primaryFinds(new short[]{5070, 6096, 7128, 8152})
		.secondaryFinds(new short[]{9160, 9164, 1816, 2977, 3022})
		.ambientAdd(30)
		.contrastAdd(100)
		.loop(false)
		.endPercent(89)
		.build()),

	// the cracks Yama's phase two shadow stomp spreads across the floor
	// (spotanim 3259, not the projectile). Starts on frame 16, where the smoke
	// ball lands and the cracks begin to spread, with the smoke hidden. The
	// cracks start from off the model's origin, so they're shifted back over the
	// tile centre, and lifted a tenth of a tile to stay clear of uneven ground.
	// The crack outline takes primary, the glowing core secondary
	YAMA_SHADOW_STOMP("Yama shadow stomp", null, BeamRecipe.builder()
		.modelId(17000)
		.animId(12110)
		.primaryFinds(new short[]{-21950, -22374})
		.secondaryFinds(new short[]{-22050})
		.hideFinds(new short[]{0})
		.translateX(-85)
		.translateY(-13)
		.translateZ(80)
		.ambientAdd(10)
		.contrastAdd(100)
		.loop(false)
		.startPercent(48)
		.endPercent(94)
		.build()),

	// the storm cloud that gathers overhead when you make a piece of sanguine
	// torva (spotanim 2294, a rainless Humidify cloud), cut as it starts to
	// shrink away. Darker puffs take primary, lighter ones secondary
	BLOOD_TORVA("Blood torva", null, BeamRecipe.builder()
		.modelId(46950)
		.animId(6307)
		.primaryFinds(new short[]{-22502, -22498})
		.secondaryFinds(new short[]{-22493, -22489})
		.loop(false)
		.endPercent(92)
		.build()),
	;

	private final String displayName;

	// plays first when present, as a lightened flash of the secondary colour
	@Nullable
	private final BeamRecipe warningRecipe;

	private final BeamRecipe recipe;

	// spotanim 2197's model with its recolourable face groups (dumped from the
	// cache) driven by the colour pickers instead of the baked ToA red
	private static BeamRecipe lightningRecipe()
	{
		return BeamRecipe.builder()
			.modelId(40177)
			.animId(8680)
			.primaryFinds(new short[]{-32663, -32649, -32533, -32543, -32572, -32560})
			.ambientAdd(60)
			.contrastAdd(60)
			.loop(false)
			.build();
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

